from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallMovingAverageAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .Strikes(-100, 100)
                .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.current_chain = None
        self.current_session_date = None
        self.last_spy_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.expiration_stop_processed = False
        self.no_entry_today = False
        self.last_handling_debug_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.TimeStop
        )

    def OnData(self, slice: Slice):
        self.current_chain = slice.OptionChains.get(self.option_symbol)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self.last_spy_price = spy_bar.Close

            local_time = self.Time.time()
            if time(9, 30) <= local_time < time(16, 0):
                if self.current_session_date != self.Time.date():
                    self.consolidator.Reset()
                    self.current_session_date = self.Time.date()

                self.consolidator.Update(spy_bar)

        self.ProcessExpiration()
        self.ProcessProfitTarget(slice)
        self.HandleUnexpectedSpyPosition()

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy:
            return

        bar_time = bar.EndTime.time()
        if not (time(9, 30) <= bar.EndTime.time() <= time(16, 0)):
            return

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        if not (time(9, 45) <= bar.EndTime.time() <= time(14, 30)):
            return

        if self.no_entry_today:
            return

        if self.held_option is not None or self.IsEntryOrderOpen():
            return

        previous_fast = self.fast_window[1]
        previous_slow = self.slow_window[1]
        current_fast = self.fast_window[0]
        current_slow = self.slow_window[0]

        bullish_crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_crossover:
            self.TryEnterCall(float(bar.Close))

    def TryEnterCall(self, spy_price: float):
        if self.current_chain is None:
            self.Debug("Skipped selection: current Slice has no SPY option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(self.current_chain)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped selection: no expiration satisfies the seven-day rule.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={selected.Expiry.date()} strike={selected.Strike}"
        )

    def ProcessProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Filled
        ):
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
            quantity = -self.Portfolio[self.held_option].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    quantity,
                    tag="50% profit target"
                )
                self.Debug(
                    f"Exit submitted: 50% profit target for {self.held_option}"
                )

    def TimeStop(self):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        if self.Time.date() != self.PreviousTradingDay(expiry):
            return

        self.CancelOpenExitOrder()
        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                quantity,
                tag="expiration time stop"
            )
            self.Debug(f"Exit submitted: expiration time stop for {self.held_option}")

    def ProcessExpiration(self):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        if self.Time.date() < expiry:
            return

        if not self.expiration_stop_processed:
            self.expiration_stop_processed = True
            self.no_entry_today = True
            self.CancelOpenExitOrder()

            quantity = -self.Portfolio[self.held_option].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    quantity,
                    tag="expiration liquidation"
                )
                self.Debug(
                    f"Exit submitted: expiration liquidation for {self.held_option}"
                )

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def IsEntryOrderOpen(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            self.exit_ticket.Cancel("Canceled by higher-priority liquidation")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_stop_processed = False
                self.Debug(
                    f"Entry filled: {self.held_option} price={self.entry_price}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                if self.held_option == order_event.Symbol:
                    self.held_option = None
                    self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.no_entry_today = True
        self.Debug("Unexpected exercise or assignment processed.")

        if self.Portfolio[self.spy].Quantity != 0:
            self.Liquidate(self.spy, tag="unexpected assignment handling")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if self.last_handling_debug_date != self.Time.date():
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.last_handling_debug_date = self.Time.date()

        self.no_entry_today = True
        self.Liquidate(self.spy, tag="unexpected SPY equity liquidation")
